3	namespace App\Filament\Widgets;
4	
5	use App\Filament\Widgets\Concerns\GroupsActivitiesByType;
6	use Filament\Support\RawJs;
7	use Filament\Widgets\ChartWidget;
8	use Illuminate\Support\Collection;
9	
10	/**
11	 * Km totali percorsi per tipo di attività, filtrati per il periodo
12	 * selezionato in dashboard. Affiancato in dashboard a DistanceShareChartWidget
13	 * nella sezione "Km attività".
14	 */
15	class DistanceByTypeChartWidget extends ChartWidget
16	{
17	    use GroupsActivitiesByType;
18	
19	    protected static ?string $heading = null;
20	
21	    protected static ?string $maxHeight = '320px';
22	
23	    /**
24	     * Oltre le barre più grandi il resto viene accorpato in "Altro".
25	     */
26	    private const MAX_BARS = 7;
27	
28	    protected function getType(): string
29	    {
30	        return 'bar';
31	    }
32	
33	    protected function getData(): array
34	    {
35	        $bars = $this->getBars();
36	
37	        if ($bars->isEmpty()) {
38	            return [
39	                'datasets' => [['data' => []]],
40	                'labels' => [],
41	            ];
42	        }
43	
44	        return [
45	            'datasets' => [
46	                [
47	                    'label' => 'Km totali',
48	                    'data' => $bars->pluck('value')->all(),
49	                    'backgroundColor' => $bars->pluck('color')->all(),
50	                ],
51	            ],
52	            'labels' => $bars->pluck('label')->all(),
53	        ];
54	    }
55	
56	    protected function getOptions(): RawJs
57	    {
58	        return RawJs::make(<<<'JS'
59	            {
60	                indexAxis: 'y',
61	                scales: {
62	                    x: {
63	                        beginAtZero: true,
64	                    },
65	                    y: {
66	                        ticks: {
67	                            // km totale già visibile sull'etichetta della barra
68	                            callback: function (value, index) {
69	                                const label = this.getLabelForValue(value);
70	                                const km = this.chart.data.datasets[0].data[index];
71	
72	                                return `${label} — ${km.toLocaleString('it-IT')} km`;
73	                            },
74	                        },
75	                    },
76	                },
77	                plugins: {
78	                    legend: {
79	                        display: false,
80	                    },
81	                    tooltip: {
82	                        callbacks: {
83	                            label: (context) => ` ${context.parsed.x.toLocaleString('it-IT')} km`,
84	                        },
85	                    },
86	                },
87	            }
88	        JS);
89	    }
90	
91	    /**
92	     * @return Collection<int, array{value: float, label: string, color: string}>
93	     */
94	    private function getBars(): Collection
95	    {
96	        $totals = $this->getTypeTotals('COALESCE(SUM(distance), 0)');
97	
98	        return $this->mapTypeTotalsToRows(
99	            $totals,
100	            self::MAX_BARS,
101	            fn (mixed $total): float => round(((float) $total) / 1000, 1),
102	        );
103	    }
104	}
