138	     * non ha icone sportive dedicate, Tabler sì. Dove manca un'icona
139	     * specifica si usa quella dello sport più simile della stessa famiglia.
140	     */
141	    public function getIcon(): string
142	    {
143	        return match ($this) {
144	            self::Run, self::VirtualRun => 'tabler-run',
145	            self::Ride, self::VirtualRide, self::EBikeRide, self::Velomobile, self::Handcycle => 'tabler-bike',
146	            self::Walk => 'tabler-walk',
147	            self::Hike, self::Snowshoe, self::RockClimbing => 'tabler-mountain',
148	            self::AlpineSki, self::BackcountrySki, self::NordicSki, self::RollerSki => 'tabler-ski-jumping',
149	            self::Snowboard => 'tabler-snowboarding',
150	            self::IceSkate => 'tabler-ice-skating',
151	            self::InlineSkate => 'tabler-roller-skating',
152	            self::Skateboard => 'tabler-skateboarding',
153	            self::Golf => 'tabler-golf',
154	            self::Yoga => 'tabler-yoga',
155	            self::Swim => 'tabler-swimming',
156	            self::Kayaking, self::Canoeing, self::Rowing, self::StandUpPaddling => 'tabler-kayak',
157	            self::Sail, self::Windsurf, self::Kitesurf, self::Surfing => 'tabler-sailboat',
158	            self::Soccer => 'tabler-ball-football',
159	            self::Wheelchair => 'tabler-wheelchair',
160	            self::Crossfit, self::WeightTraining, self::Workout => 'tabler-barbell',
161	            self::Elliptical => 'tabler-treadmill',
162	            self::StairStepper => 'tabler-stairs',
163	        };
164	    }
165	
166	    /**
167	     * Le attività a piedi si esprimono in passo (min/km), le altre in km/h.
168	     */
169	    public function getSpeedUnit(): SpeedUnit
170	    {
171	        return match ($this) {
172	            self::Run, self::VirtualRun, self::Walk, self::Hike, self::Snowshoe => SpeedUnit::MinutesPerKilometer,
173	            default => SpeedUnit::KilometersPerHour,
174	        };
175	    }
176	
177	    public function formatSpeed(?float $metersPerSecond): string
178	    {
179	        return $this->getSpeedUnit()->format($metersPerSecond);
180	    }
181	}
