3	namespace App\Filament\Widgets;
4	
5	use App\Filament\Widgets\Concerns\GroupsActivitiesByType;
6	use Filament\Support\RawJs;
7	use Filament\Widgets\ChartWidget;
8	use Illuminate\Support\Collection;
9	
10	/**
11	 * Ripartizione percentuale dei km per tipo di attività, filtrata per il
12	 * periodo selezionato in dashboard. Affiancato in dashboard a
13	 * DistanceByTypeChartWidget nella sezione "Km attività".
14	 */
15	class DistanceShareChartWidget extends ChartWidget
16	{
17	    use GroupsActivitiesByType;
18	
19	    protected static ?string $heading = null;
20	
21	    protected static ?string $maxHeight = '320px';
22	
23	    /**
24	     * Oltre le fette più grandi il resto viene accorpato in "Altro",
25	     * altrimenti una torta con troppe fette diventa illeggibile.
26	     */
27	    private const MAX_SLICES = 7;
28	
29	    protected function getType(): string
30	    {
31	        return 'pie';
32	    }
33	
34	    protected function getData(): array
35	    {
36	        $slices = $this->getSlices();
37	
38	        if ($slices->isEmpty()) {
39	            return [
40	                'datasets' => [['data' => []]],
41	                'labels' => [],
42	            ];
43	        }
44	
45	        return [
46	            'datasets' => [
47	                [
48	                    'label' => 'Km',
49	                    'data' => $slices->pluck('value')->all(),
50	                    'backgroundColor' => $slices->pluck('color')->all(),
51	                    // bordo trasparente = 2px di superficie fra le fette, in entrambi i temi
52	                    'borderColor' => 'transparent',
53	                    'borderWidth' => 2,
54	                ],
55	            ],
56	            'labels' => $slices->pluck('label')->all(),
57	        ];
58	    }
59	
60	    protected function getOptions(): RawJs
61	    {
62	        return RawJs::make(<<<'JS'
63	            {
64	                plugins: {
65	                    legend: {
66	                        position: 'right',
67	                        labels: {
68	                            boxWidth: 12,
69	                            boxHeight: 12,
70	                            usePointStyle: true,
71	                            pointStyle: 'circle',
72	                            // i km assoluti sono già visibili nel grafico a barre affiancato,
73	                            // qui in legenda mostriamo solo la percentuale
74	                            generateLabels: (chart) => {
75	                                const { labels, datasets } = chart.data;
76	                                const total = datasets[0].data.reduce((sum, value) => sum + value, 0);
77	
78	                                return labels.map((label, i) => {
79	                                    const percentage = total ? (datasets[0].data[i] / total * 100) : 0;
80	
81	                                    return {
82	                                        text: `${label}: ${percentage.toFixed(1)}%`,
83	                                        fillStyle: datasets[0].backgroundColor[i],
84	                                        strokeStyle: datasets[0].backgroundColor[i],
85	                                        pointStyle: 'circle',
86	                                        index: i,
87	                                    };
88	                                });
89	                            },
90	                        },
91	                    },
92	                    tooltip: {
93	                        callbacks: {
94	                            label: (context) => {
95	                                const total = context.dataset.data.reduce((sum, value) => sum + value, 0);
96	                                const percentage = total ? (context.parsed / total * 100) : 0;
97	
98	                                return ` ${context.label}: ${context.parsed.toLocaleString('it-IT')} km (${percentage.toFixed(1)}%)`;
99	                            },
100	                        },
101	                    },
102	                },
103	            }
104	        JS);
105	    }
106	
107	    /**
108	     * @return Collection<int, array{value: float, label: string, color: string}>
109	     */
110	    private function getSlices(): Collection
111	    {
112	        $totals = $this->getTypeTotals('COALESCE(SUM(distance), 0)');
113	
114	        return $this->mapTypeTotalsToRows(
115	            $totals,
116	            self::MAX_SLICES,
117	            fn (mixed $total): float => round(((float) $total) / 1000, 1),
118	        );
119	    }
120	}
