14	 * Trend al posto di HasActivityPeriodFilter: i dati del grafico sono già
15	 * aggregati per mese, un DatePicker a livello di giorno sarebbe fuorviante.
16	 */
17	trait HasMonthlyPeriodFilter
18	{
19	    use HasFiltersForm {
20	        mountHasFilters as baseMountHasFilters;
21	    }
22	
23	    /**
24	     * Vedi il commento gemello in HasActivityPeriodFilter: sovrascriviamo
25	     * mountHasFilters (anziché un mount() separato) perché Livewire lo
26	     * invoca dopo mount(), quando $this->filters è già stato ripristinato
27	     * da sessione/URL.
28	     */
29	    public function mountHasFilters(): void
30	    {
31	        $this->baseMountHasFilters();
32	
33	        if (filled($this->filters['startDate'] ?? null) || filled($this->filters['endDate'] ?? null)) {
34	            return;
35	        }
36	
37	        $months = $this->getUserActivitiesMonthRange();
38	
39	        $this->filters['startDate'] = Carbon::createFromFormat('Y-m', $months->first())->startOfMonth()->toDateString();
