50	    {
51	        return $form
52	            ->schema([
53	                Select::make('startDate')
54	                    ->label('Mese da')
55	                    ->options(fn () => $this->getMonthOptions(fn (Carbon $date) => $date->startOfMonth()))
56	                    ->native(false)
57	                    // ->searchable()
58	                    ->preload()
59	                    ->live(),
60	
61	                Select::make('endDate')
62	                    ->label('Mese a')
63	                    ->options(fn () => $this->getMonthOptions(fn (Carbon $date) => $date->endOfMonth()))
64	                    ->native(false)
65	                    // ->searchable()
66	                    ->preload()
67	                    ->live(),
68	            ])
69	            ->columns(2);
70	    }
