73	     * @param  callable(Carbon $date): Carbon  $boundary
74	     * @return array<string, string>
75	     */
76	    protected function getMonthOptions(callable $boundary): array
77	    {
78	        return $this->getUserActivitiesMonthRange()
79	            ->mapWithKeys(fn (string $month) => [
80	                $boundary(Carbon::createFromFormat('Y-m', $month))->toDateString() => ucfirst(
81	                    Carbon::createFromFormat('Y-m', $month)->locale('it')->translatedFormat('F Y')
82	                ),
83	            ])
84	            ->all();
85	    }
