87	    /**
88	     * Mesi (formato 'Y-m') fra la prima e l'ultima attività dell'utente.
89	     *
90	     * @return Collection<int, string>
91	     */
92	    protected function getUserActivitiesMonthRange(): Collection
93	    {
94	        return once(function () {
95	            $bounds = Activity::query()
96	                ->where('user_id', auth()->id())
97	                ->selectRaw('min(start_date_local) as min, max(start_date_local) as max')
98	                ->first();
99	
100	            $start = $bounds?->min ? Carbon::parse($bounds->min) : Carbon::now();
101	            $end = $bounds?->max ? Carbon::parse($bounds->max) : Carbon::now();
102	
103	            $months = collect();
104	            $cursor = $start->copy()->startOfMonth();
105	
106	            while ($cursor->lte($end)) {
107	                $months->push($cursor->format('Y-m'));
108	                $cursor->addMonth();
109	            }
110	
111	            return $months;
112	        });
