129	     * @return array<string, string>
130	     */
131	    protected function getMonthOptions(callable $boundary): array
132	    {
133	        return $this->getUserActivitiesMonthRange()
134	            ->mapWithKeys(fn (string $month) => [
135	                $boundary(Carbon::createFromFormat('Y-m', $month))->toDateString() => ucfirst(
136	                    Carbon::createFromFormat('Y-m', $month)->locale('it')->translatedFormat('F Y')
137	                ),
138	            ])
139	            ->all();
140	    }
141	
142	    /**
143	     * Mesi (formato 'Y-m') fra la prima e l'ultima attività dell'utente.
144	     *
145	     * @return Collection<int, string>
146	     */
147	    protected function getUserActivitiesMonthRange(): Collection
148	    {
149	        return once(function () {
150	            $bounds = Activity::query()
151	                ->where('user_id', auth()->id())
152	                ->selectRaw('min(start_date_local) as min, max(start_date_local) as max')
153	                ->first();
154	
155	            $start = $bounds?->min ? Carbon::parse($bounds->min) : Carbon::now();
156	            $end = $bounds?->max ? Carbon::parse($bounds->max) : Carbon::now();
157	
158	            $months = collect();
159	            $cursor = $start->copy()->startOfMonth();
160	
161	            while ($cursor->lte($end)) {
162	                $months->push($cursor->format('Y-m'));
163	                $cursor->addMonth();
164	            }
165	
166	            return $months;
167	        });
